"""comtypes wrappers are generated by one process at a time, and retried.

Four xdist workers importing eda_agent.ui.menu at once on a fresh venv all
generated oleacc's wrapper into comtypes/gen together. One of them read a
half-written file, set _AVAILABLE = False, and failed eight menu tests;
the next run of the same venv passed, because the wrapper then existed.
"""
from __future__ import annotations

import subprocess
import sys
import textwrap
import threading
import time

import pytest

from eda_agent.ui import comgen

client = pytest.importorskip("comtypes.client")


@pytest.fixture(autouse=True)
def own_lock(tmp_path, monkeypatch):
    monkeypatch.setattr(comgen, "lock_path", lambda: str(tmp_path / "gen.lock"))
    monkeypatch.setattr(comgen.time, "sleep", lambda _s: None)


def test_a_failed_generation_is_tried_again(monkeypatch):
    calls = []

    def flaky(name):
        calls.append(name)
        if len(calls) < 3:
            raise SyntaxError("half-written wrapper")
        return "module"

    monkeypatch.setattr(client, "GetModule", flaky)
    assert comgen.get_module("oleacc.dll") == "module"
    assert calls == ["oleacc.dll"] * 3


def test_the_last_error_is_raised_when_every_try_fails(monkeypatch):
    calls = []

    def broken(name):
        calls.append(name)
        raise OSError("no type library")

    monkeypatch.setattr(client, "GetModule", broken)
    with pytest.raises(OSError, match="no type library"):
        comgen.get_module("x.dll", attempts=3)
    assert len(calls) == 3


def test_threads_generate_one_at_a_time(monkeypatch):
    inside, most, lock = [0], [0], threading.Lock()
    real_sleep = time.sleep

    def slow(name):
        with lock:
            inside[0] += 1
            most[0] = max(most[0], inside[0])
        real_sleep(0.05)
        with lock:
            inside[0] -= 1
        return name

    monkeypatch.setattr(client, "GetModule", slow)
    out = []
    threads = [threading.Thread(target=lambda: out.append(comgen.get_module("a.dll")))
               for _ in range(4)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(10)
    assert out == ["a.dll"] * 4
    assert most[0] == 1


def test_processes_generate_one_at_a_time(tmp_path):
    """The real case: separate processes, each with its own handle on the
    lock file. Each child records when it entered and left the locked
    region; no two of those spans may overlap."""
    lock, log = tmp_path / "proc.lock", tmp_path / "spans.txt"
    child = textwrap.dedent(f"""
        import time
        from eda_agent.ui import comgen
        with comgen._locked({str(lock)!r}):
            start = time.perf_counter()
            time.sleep(0.25)
            end = time.perf_counter()
        with open({str(log)!r}, "a") as f:
            f.write(f"{{start}} {{end}}\\n")
    """)
    procs = [subprocess.Popen([sys.executable, "-c", child]) for _ in range(3)]
    for p in procs:
        assert p.wait(60) == 0
    spans = sorted(tuple(map(float, line.split())) for line in log.read_text().splitlines())
    assert len(spans) == 3
    for (_, end), (start, _) in zip(spans, spans[1:]):
        assert start >= end, f"two processes held the lock together: {spans}"
